(* [comment removed for export] *)
Lemma clamp_bc : forall bc d, -16 <= d <= 0 -> 0 <= bc < 2^31 ->
  Z.land ((bc + (d mod 18446744073709551616) ≪ 3) mod 18446744073709551616) 31 = (bc + 8 * d) mod 32.
